//! python-dotenv parity. `dotenv_golden.json` is generated by `gen_dotenv_golden.py` (python-dotenv's
//! `dotenv_values`) from the synthetic `dotenv_golden.env`; the process env there is HOST_VAR=from-proc.

use fm_core::dotenv::dotenv_values;
use std::collections::{BTreeMap, HashMap};

fn proc_env() -> HashMap<String, String> {
    HashMap::from([("HOST_VAR".to_string(), "from-proc".to_string())])
}

#[test]
fn golden_matches_python_dotenv() {
    let env = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/dotenv_golden.env")).unwrap();
    let json = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/dotenv_golden.json")).unwrap();
    let expected: BTreeMap<String, Option<String>> = serde_json::from_str(&json).unwrap();
    let got: BTreeMap<String, Option<String>> = dotenv_values(&env, &proc_env()).into_iter().collect();
    assert_eq!(got, expected);
}

#[test]
fn crlf_and_bom() {
    let got = dotenv_values("\u{feff}A=1\r\nB='x y'\r\nC=\r\nD=4 # c\r\n", &HashMap::new());
    assert_eq!(got["A"].as_deref(), Some("1"));
    assert_eq!(got["B"].as_deref(), Some("x y"));
    assert_eq!(got["C"].as_deref(), Some(""));
    assert_eq!(got["D"].as_deref(), Some("4"));
}

#[test]
fn bad_line_does_not_fail_file() {
    let got = dotenv_values("A=1\nthis is bad\nB=2\n", &HashMap::new());
    assert_eq!(got["A"].as_deref(), Some("1"));
    assert_eq!(got["B"].as_deref(), Some("2"));
}

/// Ignored: prints key names and value lengths only, for comparison with python-dotenv.
#[test]
#[ignore]
fn real_env_names_and_lengths() {
    let path = std::env::var("FM_REAL_ENV").unwrap_or_else(|_| "C:/code/fantasy_manager/.env".into());
    let content = std::fs::read_to_string(path).unwrap();
    let env: HashMap<String, String> = std::env::vars().collect();
    let got: BTreeMap<String, Option<String>> = dotenv_values(&content, &env).into_iter().collect();
    for (k, v) in &got {
        println!("KEYLEN {} {}", k, v.as_ref().map_or(-1, |v| v.chars().count() as i64));
    }
    println!("KEYCOUNT {}", got.len());
}
